import React, { useEffect, useState } from "react";
import CarouselQuantityDiscounts from "./CarouselQuantityDiscountsSmall";
import WholesalersCarousel from "./WholesalersCarousel";
import useApi from "./../../../hooks/useApi";
import entitiesApi from "../../../api/entitiesApi";
import CarouselQuantityDiscountsSmall from "./CarouselQuantityDiscountsSmall";
import { useNavigate, useParams } from "react-router-dom";
import { Avatar, Card, CardHeader } from "@heroui/react";

export default function MarketPlace() {
  const getWholesalersApi = useApi(entitiesApi.entitiesAction);
  const [wholesalers, setwholesalers] = useState([]);
  const getWholesalers = async () => {
    await getWholesalersApi.request({
      action: "GetWholesaleEntities",
    });
  };

  useEffect(() => {
    getWholesalers();
  }, []);

  useEffect(() => {
    if (getWholesalersApi.data && getWholesalersApi.data.length) {
      setwholesalers(getWholesalersApi.data);
    }
    console.log("getWholesalersApi.data", getWholesalersApi.data);
  }, [getWholesalersApi.data]);

  const [selectedWholesaler, setselectedWholesaler] = useState();


  const navigate = useNavigate();

  const handleClick = (item) => {

    setselectedWholesaler(item);
    navigate(`/marketplace/wholesaler/cart/${item.id}`, {
      state: {
        id: item.id,
        title: item.title,
      },
    });
  };

  return (
    <div className="m-auto h-screen grid grid-cols-12 mt-14 md:mt-7 w-full ">

      <div className="col-span-2"></div>
      <div className="col-span-8  grid grid-cols-1 md:grid-cols-3">

        {wholesalers.map((item) => {
          return (
            <Card isPressable
              className="shadow-md rounded-md w-full  max-h-36"
              onPress={() => handleClick(item)}
            >

              <CardHeader className="justify-start ">

                <Avatar isBordered
                  radius="full"
                  size="md"
                  src="https://heroui.com/avatars/avatar-1.png" />

                <div className="flex flex-col gap-1 items-start justify-start mx-2">
                  <h4 className="text-small font-semibold leading-none text-default-600 uppercase">{item.title}</h4>
                  <h5 className="text-small tracking-tight text-default-400">{item.town}</h5>
                </div>
              </CardHeader>

            </Card>
          );
        })}
      </div>

      <div className="col-span-2"></div>
    </div>

  );
}